def normalize(path):
    """A slash-separated path in its shortest form. See TASK.md."""
    is_absolute = path.startswith('/')

    segments = []
    for seg in path.split('/'):
        if seg in ('', '.'):
            continue
        elif seg == '..':
            if segments and segments[-1] != '..':
                segments.pop()
            elif not is_absolute:
                segments.append('..')
        else:
            segments.append(seg)

    if is_absolute:
        result = '/' + '/'.join(segments)
    else:
        result = '/'.join(segments) if segments else '.'

    return result


def join(base, *parts):
    """`base` with each part applied, normalised. See TASK.md."""
    current = base
    for part in parts:
        if not part:
            continue
        if part.startswith('/'):
            current = part
        else:
            current = current + '/' + part

    return normalize(current)
